/* HorizenMessages - single Cloudflare Worker.
   Serves the app at EVERY path (/, /oauth/consent, /email-confirmation, ...) so the OAuth login
   and confirmation emails work. */
const HTML = "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>HorizenMessages</title>\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.95.3\"></script>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#0e1424;--panel:#161e36;--line:#26304f;--tx:#e8ecf7;--mut:#8a95b5;--ac:#6ea8ff;--ok:#4fd1a5;--bad:#ff6b6b}\n*{box-sizing:border-box}html,body{height:100%;margin:0}\nbody{background:var(--bg);color:var(--tx);font:15px/1.4 \"Avenir Next\",Segoe UI,system-ui,sans-serif}\nbutton,input{font:inherit;color:inherit}\ninput{background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:10px 12px;width:100%}\ninput:focus-visible,button:focus-visible{outline:2px solid var(--ac);outline-offset:1px}\nbutton{background:var(--ac);color:#08101f;border:0;border-radius:8px;padding:9px 14px;cursor:pointer;font-weight:600}\nbutton.g{background:transparent;color:var(--tx);border:1px solid var(--line)}\nbutton.r{background:var(--bad);color:#fff}\n[hidden]{display:none!important}\n#auth{display:grid;place-items:center;height:100%;padding:16px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:24px;width:100%;max-width:360px;display:grid;gap:10px}\n.card h1{margin:0 0 4px;font-size:24px}.mut{color:var(--mut);font-size:13px}\n#app{display:flex;height:100%}\n#side{width:320px;border-right:1px solid var(--line);display:flex;flex-direction:column;background:var(--panel)}\n#side header,#head{padding:12px 14px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:8px}\n#side header b{flex:1}\n.tabs{display:flex;border-bottom:1px solid var(--line)}\n.tabs button{flex:1;background:none;color:var(--mut);border-radius:0;border-bottom:2px solid transparent}\n.tabs button.on{color:var(--tx);border-color:var(--ac)}\n.list{overflow:auto;flex:1}\n.row{padding:12px 14px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:8px;cursor:pointer}\n.row:hover,.row.on{background:#1d2748}.row span{flex:1;overflow:hidden;text-overflow:ellipsis}\n.pad{padding:12px 14px;display:grid;gap:8px}\n#main{flex:1;display:flex;flex-direction:column;min-width:0}\n#head b{flex:1}\n#msgs{flex:1;overflow:auto;padding:16px;display:flex;flex-direction:column;gap:6px}\n.m{max-width:70%;padding:8px 12px;border-radius:14px;background:var(--panel);align-self:flex-start;word-wrap:break-word}\n.m.me{background:var(--ac);color:#08101f;align-self:flex-end}\n.m small{display:block;color:var(--mut);font-size:11px}.m.me small{color:#2b3a5e}\n#send{display:flex;gap:8px;padding:12px;border-top:1px solid var(--line)}\n.empty{margin:auto;color:var(--mut);text-align:center}\n#call{position:fixed;inset:0;background:#05080f;display:grid;grid-template-rows:1fr auto;z-index:9}\n#rv{width:100%;height:100%;object-fit:contain;background:#000;min-height:0}\n#lv{position:absolute;right:16px;top:16px;width:140px;border-radius:10px;border:1px solid var(--line);background:#000}\n#cb{padding:16px;text-align:center}\n#back{display:none}\n@media(max-width:700px){#side{width:100%}#main{display:none}#app.open #side{display:none}#app.open #main{display:flex}#back{display:block}}\n\n/* ---- Horizen glow theme ---- */\n:root{--bg:#070a14;--panel:rgba(22,30,58,.62);--line:rgba(130,150,255,.16);--ac:#7c8cff;--ac2:#b46bff;--grad:linear-gradient(135deg,#6ea8ff,#7c5cff 55%,#c05bff)}\nbody{background:radial-gradient(900px 600px at 8% -10%,rgba(124,92,255,.35),transparent 60%),radial-gradient(800px 600px at 100% 110%,rgba(46,196,255,.22),transparent 60%),var(--bg);background-attachment:fixed}\n.card,#side,#head,#send,.tabs{backdrop-filter:blur(18px) saturate(140%);-webkit-backdrop-filter:blur(18px) saturate(140%)}\n.card{border-radius:20px;box-shadow:0 20px 60px rgba(0,0,0,.5),0 0 0 1px rgba(255,255,255,.04) inset;animation:rise .5s ease both}\n.card h1{font-size:28px;letter-spacing:-.5px;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}\n@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}\ninput{background:rgba(7,10,20,.6);border-radius:12px;transition:border-color .2s,box-shadow .2s}\ninput:focus{outline:none;border-color:var(--ac);box-shadow:0 0 0 3px rgba(124,140,255,.25)}\nbutton{background:var(--grad);color:#fff;border-radius:12px;transition:transform .15s,box-shadow .2s,filter .2s}\nbutton:hover{transform:translateY(-1px);box-shadow:0 8px 22px rgba(124,92,255,.4);filter:brightness(1.08)}\nbutton:active{transform:none}\nbutton.g{background:rgba(255,255,255,.05);border:1px solid var(--line);box-shadow:none}\nbutton.g:hover{background:rgba(255,255,255,.1);box-shadow:none}\nbutton.r{background:linear-gradient(135deg,#ff6b6b,#ff3d7f)}\n#side{background:rgba(12,16,32,.55)}\n#side header b{font-weight:700;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}\n.tabs button{background:none;box-shadow:none;transform:none;color:var(--mut)}\n.tabs button.on{color:#fff;border-image:var(--grad) 1}\n.row{margin:4px 8px;border:0;border-radius:14px;padding:10px 12px;transition:background .2s}\n.row::before{content:\"\";width:38px;height:38px;flex:none;border-radius:50%;background:var(--grad);box-shadow:0 0 14px rgba(124,92,255,.5)}\n.row:hover{background:rgba(255,255,255,.06)}.row.on{background:linear-gradient(90deg,rgba(124,140,255,.22),rgba(180,107,255,.1))}\n#head{background:rgba(12,16,32,.55)}\n#head b{font-size:17px}\n#msgs{padding:20px 18px;gap:8px;scrollbar-width:thin;scrollbar-color:#2c3560 transparent}\n.m{border-radius:18px 18px 18px 6px;background:rgba(255,255,255,.07);border:1px solid var(--line);padding:9px 14px;animation:pop .25s ease both}\n.m.me{border:0;border-radius:18px 18px 6px 18px;background:var(--grad);color:#fff;box-shadow:0 6px 20px rgba(124,92,255,.35)}\n.m.me small{color:rgba(255,255,255,.75)}\n@keyframes pop{from{opacity:0;transform:translateY(8px) scale(.97)}to{opacity:1;transform:none}}\n#send{background:rgba(12,16,32,.55);padding:14px}\n#send input{border-radius:999px;padding:12px 18px}#send button{border-radius:999px;padding:0 22px}\n.empty{font-size:16px}\n#call{background:radial-gradient(800px 500px at 50% 0,rgba(124,92,255,.3),#05080f 70%)}\n#lv{border-radius:16px;box-shadow:0 10px 30px rgba(0,0,0,.6)}#rv{border-radius:0}\n/* ---- sleek type + new features ---- */\nbody{font-family:\"Inter\",system-ui,-apple-system,\"Segoe UI\",sans-serif;font-size:14.5px;letter-spacing:-.011em;-webkit-font-smoothing:antialiased;font-feature-settings:\"cv11\",\"ss01\"}\nh1,b{letter-spacing:-.025em}.card h1{font-weight:700}.mut,small{font-weight:500}\ninput,button{font-family:inherit}button{font-weight:550;letter-spacing:-.01em}\n.m{position:relative;padding-right:30px}.m small{font-weight:500;letter-spacing:0}\n.m .mb{position:absolute;top:4px;right:4px;padding:0 6px;background:none;box-shadow:none;color:inherit;opacity:.35;font-size:16px;line-height:1.2}\n.m:hover .mb{opacity:1}.m .mb:hover{transform:none;box-shadow:none;background:rgba(255,255,255,.12)}\n.q{border-left:3px solid rgba(255,255,255,.4);padding:2px 8px;margin:4px 0;font-size:12.5px;opacity:.8;border-radius:3px}\n.m img{display:block;max-width:240px;max-height:260px;border-radius:12px;margin:4px 0}\n.fl{color:inherit;font-weight:600;text-decoration:none;display:inline-block;padding:6px 10px;margin:4px 0;border-radius:10px;background:rgba(255,255,255,.12)}\n.rx{display:flex;gap:4px;flex-wrap:wrap;margin-top:5px}\n.rx span{font-size:12px;padding:2px 8px;border-radius:999px;background:rgba(255,255,255,.1);border:1px solid var(--line);cursor:pointer}\n.rx span.mine{border-color:var(--ac);background:rgba(124,140,255,.28)}\n.pop{position:absolute;z-index:5;top:100%;right:0;margin-top:4px;display:flex;gap:4px;align-items:center;flex-wrap:wrap;max-width:260px;padding:8px;border-radius:14px;background:#161e36;border:1px solid var(--line);box-shadow:0 12px 36px rgba(0,0,0,.6)}\n.pop span{cursor:pointer;font-size:20px;padding:2px 3px}.pop button{padding:5px 10px;font-size:12.5px}\n#rp{display:flex;align-items:center;gap:8px;padding:8px 14px;border-top:1px solid var(--line);color:var(--mut);font-size:13px;background:rgba(12,16,32,.55)}\n#rp[hidden]{display:none}#rp button{padding:2px 8px;margin-left:auto}\n#at{padding:0 15px;font-size:18px}\n#st{font-size:12px;color:var(--mut);margin-top:1px}#st.ok{color:#4fd1a5}\n.row.onl::before{box-shadow:0 0 0 2px #0b1020,0 0 0 4px #4fd1a5}\n#inc{position:fixed;inset:0;z-index:10;display:grid;place-items:center;background:rgba(5,8,15,.78);backdrop-filter:blur(8px)}\n#inc .card{text-align:center;max-width:320px}#inc .card>div:last-child{justify-content:center}\n/* ---- settings, avatars, add members, toast ---- */\n.row::before{background:var(--av,var(--grad)) center/cover}\n#who{cursor:pointer;display:flex;align-items:center;gap:9px}\n#who::before{content:\"\";width:30px;height:30px;flex:none;border-radius:50%;background:var(--av,var(--grad)) center/cover;box-shadow:0 0 12px rgba(124,92,255,.5)}\n.ov{position:fixed;inset:0;z-index:10;display:grid;place-items:center;background:rgba(5,8,15,.78);backdrop-filter:blur(8px)}\n.ov .card{display:flex;flex-direction:column;gap:10px;min-width:280px;max-width:340px;max-height:85vh;overflow:auto}\n.bigav{width:96px;height:96px;border-radius:50%;margin:0 auto;background:var(--av,var(--grad)) center/cover;box-shadow:0 0 28px rgba(124,92,255,.55)}\n#sun{text-align:center;font-weight:600;font-size:16px;color:var(--tx)}\n.pk{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:10px;cursor:pointer}.pk:hover{background:rgba(255,255,255,.06)}\n.pk input{width:auto}\n#toast{position:fixed;left:50%;bottom:90px;transform:translateX(-50%);z-index:20;padding:10px 16px;border-radius:999px;background:#161e36;border:1px solid var(--line);box-shadow:0 10px 30px rgba(0,0,0,.5)}\n/* ---- eaglercraft party cards + game panel ---- */\n.pty{display:flex;flex-direction:column;gap:3px;min-width:220px;padding:4px 0}\n.pty b{font-size:15px}.pty span{font-size:12px;opacity:.8}.pty div{display:flex;gap:6px;margin-top:6px}\n.pty button{padding:6px 12px;font-size:13px;position:static}\n.m.me .pty button.g{background:rgba(255,255,255,.18);color:#fff}\n#pg{position:fixed;top:0;right:0;bottom:0;width:min(100vw,68vw);z-index:15;display:flex;flex-direction:column;background:#070a14;border-left:1px solid var(--line);box-shadow:-20px 0 60px rgba(0,0,0,.6)}\n#pg .top{padding:8px 12px;gap:8px}#pg .top b{flex:1}\n#pgf{flex:1;width:100%;border:0;background:#000}\n@media(max-width:700px){#pg{width:100vw}}\n</style></head><body>\n\n<section id=\"auth\" hidden>\n <div class=\"card\">\n  <h1>HorizenMessages</h1>\n  <input id=\"un\" placeholder=\"Username (sign up only)\" autocomplete=\"username\">\n  <input id=\"em\" type=\"email\" placeholder=\"Email\" autocomplete=\"email\">\n  <input id=\"pw\" type=\"password\" placeholder=\"Password\" autocomplete=\"current-password\">\n  <button id=\"li\">Log in</button>\n  <button id=\"su\" class=\"g\">Create account</button>\n  <button id=\"oc\" class=\"g\">Email me a sign-in code</button>\n  <input id=\"cd\" inputmode=\"numeric\" autocomplete=\"one-time-code\" placeholder=\"Code from your email\" hidden>\n  <button id=\"ov\" hidden>Verify code</button>\n  <div class=\"mut\" style=\"text-align:center\">or</div>\n  <button id=\"gh\" class=\"g\" style=\"display:flex;align-items:center;justify-content:center;gap:10px\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12\"/></svg>Continue with GitHub</button>\n  <div id=\"am\" class=\"mut\" role=\"status\"></div>\n </div>\n</section>\n\n<section id=\"done\" hidden>\n <div class=\"card\"><h1 id=\"dh\">Confirming…</h1><div class=\"mut\" id=\"dm\"></div><button id=\"go\" hidden>Open HorizenMessages</button> <button id=\"deny\" class=\"g\" hidden>Deny</button></div>\n</section>\n\n<div id=\"app\" hidden>\n <aside id=\"side\">\n  <header><b id=\"who\"></b><button class=\"g\" id=\"lo\">Log out</button></header>\n  <div class=\"tabs\"><button id=\"t1\" class=\"on\">Chats</button><button id=\"t2\">Friends</button></div>\n  <div id=\"chats\" class=\"list\"></div>\n  <div id=\"friends\" class=\"list\" hidden>\n   <div class=\"pad\"><input id=\"fu\" placeholder=\"Add friend by username\"><button id=\"fa\">Send request</button></div>\n   <div id=\"fl\"></div>\n  </div>\n </aside>\n <main id=\"main\">\n  <div id=\"head\" hidden>\n   <button class=\"g\" id=\"back\">Back</button><div style=\"flex:1;min-width:0\"><b id=\"cn\"></b><div id=\"st\"></div></div>\n   <button class=\"g\" id=\"ad\" title=\"Add people\" hidden>＋👤</button> <button class=\"g\" id=\"ca\">Call</button><button class=\"g\" id=\"cv\">Video call</button>\n  </div>\n  <div id=\"msgs\"><div class=\"empty\">Choose a chat, or add a friend to start one.</div></div>\n  <div id=\"rp\" hidden></div>\n  <form id=\"send\" hidden><button type=\"button\" class=\"g\" id=\"at\" aria-label=\"Attach file\">＋</button><input type=\"file\" id=\"fi\" hidden><input id=\"mi\" placeholder=\"Write a message\" autocomplete=\"off\"><button>Send</button></form>\n </main>\n</div>\n\n<div id=\"set\" class=\"ov\" hidden><div class=\"card\"><h1>Settings</h1><div id=\"sav\" class=\"bigav\"></div><div id=\"sun\"></div>\n <button class=\"g\" id=\"sup\">Change profile icon</button><input type=\"file\" id=\"sf\" accept=\"image/*\" hidden>\n <button class=\"g\" id=\"sn\">Enable notifications</button><button id=\"sx\">Done</button><button class=\"r\" id=\"slo\">Log out</button></div></div>\n<div id=\"pk\" class=\"ov\" hidden><div class=\"card\"><h1>Add people</h1><div id=\"pl\"></div><button id=\"pa\">Add to group</button><button class=\"g\" id=\"pc\">Cancel</button></div></div>\n<div id=\"pg\" hidden><div class=\"top\"><b id=\"pgt\"></b><button class=\"g\" id=\"pgo\">Open in new tab</button><button class=\"r\" id=\"pgx\">Close</button></div><iframe id=\"pgf\" title=\"Eaglercraft\" allow=\"fullscreen; autoplay; keyboard-map; clipboard-write\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe></div>\n<div id=\"toast\" hidden></div>\n<div id=\"inc\" hidden><div class=\"card\"><h1 id=\"in\"></h1><div class=\"mut\" id=\"it\"></div><div style=\"display:flex;gap:8px\"><button id=\"ac\">Answer</button><button class=\"r\" id=\"dc\">Decline</button></div></div></div>\n\n<div id=\"call\" hidden>\n <video id=\"rv\" autoplay playsinline></video><video id=\"lv\" autoplay playsinline muted></video>\n <div id=\"cb\"><div id=\"cs\" class=\"mut\"></div><button class=\"g\" id=\"mu\">Mute</button> <button class=\"r\" id=\"hu\">Hang up</button></div>\n</div>\n\n<script>\nconst sb=supabase.createClient('https://wzfdomantqeaedfexpgq.supabase.co','sb_publishable_vrz02Sm0olhxPqgc1MihJg_mrEMh7MG');\n// Link in the confirmation email. Replace website.com with your domain.\nconst CONFIRM_URL='https://website.com/email-confirmation';\nconst $=id=>document.getElementById(id);\nconst esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nlet me,P={},convs=[],cur=null,started=false;\n\n/* ---------- Auth + email confirmation ---------- */\nconst note=t=>$('am').textContent=t;\n$('su').onclick=async()=>{\n  const username=$('un').value.trim(),email=$('em').value.trim(),password=$('pw').value;\n  if(!username||!email||password.length<6)return note('Enter a username, email and a password of 6+ characters.');\n  const {error}=await sb.auth.signUp({email,password,options:{data:{username},emailRedirectTo:CONFIRM_URL}});\n  if(error)return note(error.message);\n  localStorage.setItem('email','confirmation'); // set when the confirmation email is sent\n  note('Confirmation email sent. Open the link in it, then log in.');\n};\n$('li').onclick=async()=>{\n  const {error}=await sb.auth.signInWithPassword({email:$('em').value.trim(),password:$('pw').value});\n  if(error)note(error.message);\n};\n$('lo').onclick=()=>sb.auth.signOut().then(()=>location.href=location.pathname.replace(/email-confirmation.*/,''));\n$('go').onclick=()=>{location.href=location.pathname.replace(/email-confirmation.*/,'')};\n\nasync function approved(u){const {data}=await sb.from('approved_acounts').select('user_id').eq('user_id',u.id).maybeSingle();return !!data}\n/* ---------- OAuth provider: \"Log in with HorizenMessages\" consent page (/oauth/consent) ---------- */\nlet consenting=false;\nasync function consentPage(){\n  if(consenting)return;consenting=true;\n  const say=(h,m)=>{$('auth').hidden=true;$('app').hidden=true;$('done').hidden=false;$('dh').textContent=h;$('dm').textContent=m;$('go').hidden=true;$('deny').hidden=true};\n  const id=new URLSearchParams(location.search).get('authorization_id')||sessionStorage.getItem('oauth_aid');\n  if(!id){consenting=false;return say('Missing sign-in request','Start again from the app you came from.')}\n  sessionStorage.setItem('oauth_aid',id);\n  const {data:{session}}=await sb.auth.getSession();\n  if(!session){consenting=false;$('app').hidden=true;$('done').hidden=true;$('auth').hidden=false;return note('Log in to HorizenMessages to continue.')}\n  await ensureAccount(session.user);\n  if(!(await approved(session.user))){consenting=false;return say('Confirm your email first','Open the link in your confirmation email, then try again.')}\n  const {data:d,error}=await sb.auth.oauth.getAuthorizationDetails(id);\n  if(error||!d){sessionStorage.removeItem('oauth_aid');return say('Sign-in request expired',error?.message||'Start again from the app.')}\n  if(!('authorization_id' in d)){sessionStorage.removeItem('oauth_aid');return location.replace(d.redirect_url)}\n  const scopes=(d.scope||'').split(' ').filter(Boolean);\n  say('Authorize '+d.client.name,d.client.name+' wants to sign you in as '+session.user.email+(scopes.length?' and see your: '+scopes.join(', ')+'.':'.'));\n  $('go').textContent='Approve';$('go').hidden=false;$('deny').hidden=false;\n  const decide=async ok=>{\n    $('go').hidden=$('deny').hidden=true;\n    const r=ok?await sb.auth.oauth.approveAuthorization(id):await sb.auth.oauth.denyAuthorization(id);\n    sessionStorage.removeItem('oauth_aid');\n    if(r.error)return say('Something went wrong',r.error.message);\n    location.replace(r.data.redirect_url);\n  };\n  $('go').onclick=()=>decide(true);$('deny').onclick=()=>decide(false);\n}\nasync function confirmPage(){\n  $('auth').hidden=true;$('app').hidden=true;$('done').hidden=false;\n  const say=(h,m)=>{$('dh').textContent=h;$('dm').textContent=m};\n  if(localStorage.getItem('email')!=='confirmation')return say('Can\\u2019t confirm here','Open this link in the same browser you signed up with.');\n  const {data:{session}}=await sb.auth.getSession();\n  if(!session)return say('Link not verified','Try the link in your email again.');\n  const u=session.user,{error}=await sb.from('approved_acounts').upsert({user_id:u.id,email:u.email});\n  if(error)return say('Activation failed',error.message);\n  localStorage.removeItem('email');say('Email confirmed','Your account is activated.');$('go').hidden=false;\n}\nasync function boot(){\n  if(location.pathname.includes('email-confirmation'))return confirmPage();\n  if(location.pathname.includes('oauth/consent'))return consentPage();\n  const {data:{session}}=await sb.auth.getSession();\n  if(!session){$('app').hidden=true;$('auth').hidden=false;return}\n  await ensureAccount(session.user);\n  if(await approved(session.user))start(session.user);\n  else{await sb.auth.signOut({scope:'local'});$('app').hidden=true;$('auth').hidden=false;note('Your account isn\\u2019t confirmed yet. Check your email for the link.')}\n}\nsb.auth.onAuthStateChange((e,s)=>{if(e==='SIGNED_OUT'){location.reload()}else if(e==='SIGNED_IN'&&s&&!started&&!window.holdBoot&&!location.pathname.includes('email-confirmation'))boot()});\nboot();\n\nasync function start(u){\n  if(started)return;started=true;me=u;\n  $('auth').hidden=true;$('app').hidden=false;\n  await loadProfiles();$('who').textContent=P[me.id]?.username||'Me';paintSet();document.addEventListener('click',()=>{if('Notification' in window&&Notification.permission==='default')Notification.requestPermission().then(paintSet)},{once:true});\n  await Promise.all([loadConvs(),loadFriends()]);\n  sb.channel('db')\n   .on('postgres_changes',{event:'INSERT',schema:'public',table:'messages'},p=>{if(p.new.conversation_id===cur)addMsg(p.new);notifyMsg(p.new)})\n   .on('postgres_changes',{event:'UPDATE',schema:'public',table:'messages'},p=>{if(p.new.conversation_id===cur)addMsg(p.new)})\n   .on('postgres_changes',{event:'UPDATE',schema:'public',table:'profiles'},async()=>{await loadProfiles();loadConvs();loadFriends();paintSet()})\n   .on('postgres_changes',{event:'*',schema:'public',table:'reactions'},()=>{if(cur)loadReacts()})\n   .on('postgres_changes',{event:'*',schema:'public',table:'friendships'},loadFriends)\n   .on('postgres_changes',{event:'INSERT',schema:'public',table:'conversation_members'},async p=>{await loadConvs();onAdded(p.new)}).subscribe();\n  sb.channel('u:'+me.id).on('broadcast',{event:'sig'},({payload})=>onSig(payload)).subscribe();\n  const pr=sb.channel('online',{config:{presence:{key:me.id}}});\n  pr.on('presence',{event:'sync'},()=>{online=new Set(Object.keys(pr.presenceState()));paint()}).subscribe(st=>{if(st==='SUBSCRIBED')pr.track({at:Date.now()})});\n  // Opened from Horizen OS: #sig=<incoming call>, #chat=<conversation id>\n  const hs=location.hash;history.replaceState(null,'',location.pathname+location.search);\n  const hm=hs.match(/^#sig=(.+)$/),hc=hs.match(/^#chat=([\\w-]+)$/);\n  if(hm){try{const w=JSON.parse(atob(decodeURIComponent(hm[1])));if(Date.now()-w.at<45000)onSig(w.p)}catch(e){}}\n  else if(hc&&convs.find(c=>c.id===hc[1]))openConv(hc[1]);\n}\nasync function loadProfiles(){const {data}=await sb.from('profiles').select('*');(data||[]).forEach(p=>P[p.id]=p)}\nconst uname=id=>P[id]?.username||'Unknown';\n\n/* ---------- Tabs ---------- */\n$('t1').onclick=()=>tab(1);$('t2').onclick=()=>tab(2);\nfunction tab(n){$('t1').classList.toggle('on',n==1);$('t2').classList.toggle('on',n==2);$('chats').hidden=n!=1;$('friends').hidden=n!=2}\n\n/* ---------- Friends ---------- */\nlet fr=[];\nasync function loadFriends(){\n  await loadProfiles();\n  const {data}=await sb.from('friendships').select('*');fr=data||[];\n  $('fl').innerHTML=fr.map(f=>{\n    const other=f.requester===me.id?f.addressee:f.requester;\n    if(f.status==='accepted')return `<div class=\"row\" style=\"${av(other)}\"><span>${esc(uname(other))}</span><button data-dm=\"${other}\">Message</button></div>`;\n    if(f.addressee===me.id)return `<div class=\"row\"><span>${esc(uname(other))} wants to be friends</span><button data-ok=\"${f.id}\">Accept</button></div>`;\n    return `<div class=\"row\"><span>${esc(uname(other))}</span><span class=\"mut\">Request sent</span></div>`;\n  }).join('')||'<div class=\"pad mut\">No friends yet. Add one by username.</div>';\n}\n$('fl').onclick=e=>{\n  if(e.target.dataset.dm)openDM(e.target.dataset.dm);\n  if(e.target.dataset.ok)sb.from('friendships').update({status:'accepted'}).eq('id',e.target.dataset.ok).then(loadFriends);\n};\n$('fa').onclick=async()=>{\n  const n=$('fu').value.trim().toLowerCase();\n  const t=Object.values(P).find(p=>p.username.toLowerCase()===n);\n  if(!t)return alert('No user with that username.');\n  if(t.id===me.id)return alert(\"That's you.\");\n  const {error}=await sb.from('friendships').insert({requester:me.id,addressee:t.id});\n  if(error)alert(error.message);else{$('fu').value='';loadFriends()}\n};\n\n/* ---------- Conversations ---------- */\nasync function loadConvs(){\n  const {data}=await sb.from('conversations').select('*,conversation_members(user_id)').order('created_at',{ascending:false});\n  convs=data||[];\n  $('chats').innerHTML='<div class=\"pad\"><button class=\"g\" id=\"ng\">New group</button></div>'+\n    (convs.map(c=>`<div class=\"row ${c.id===cur?'on':''}\" data-c=\"${c.id}\" style=\"${c.is_group?'':av(other(c))}\"><span>${esc(cname(c))}</span>${c.is_group?'<small class=\"mut\">Group</small>':''}</div>`).join('')||'<div class=\"pad mut\">No chats yet.</div>');\n  $('ng').onclick=newGroup;paint();\n}\nconst other=c=>c.conversation_members.map(m=>m.user_id).find(i=>i!==me.id);\nconst cname=c=>c.is_group?c.name:uname(other(c));\n$('chats').onclick=e=>{const r=e.target.closest('[data-c]');if(r)openConv(r.dataset.c)};\n\nasync function mk(name,isGroup,ids){\n  const {data:c,error}=await sb.from('conversations').insert({name,is_group:isGroup,created_by:me.id}).select().single();\n  if(error)return alert(error.message);\n  const {error:e2}=await sb.from('conversation_members').insert([me.id,...ids].map(user_id=>({conversation_id:c.id,user_id})));\n  if(e2)return alert(e2.message);\n  await loadConvs();return c.id;\n}\nasync function openDM(fid){\n  let c=convs.find(c=>!c.is_group&&other(c)===fid);\n  openConv(c?c.id:await mk(null,false,[fid]));tab(1);\n}\nasync function newGroup(){\n  const name=prompt('Group name');if(!name)return;\n  const names=(prompt('Friends to add (usernames, comma separated)')||'').split(',').map(s=>s.trim().toLowerCase());\n  const ids=fr.filter(f=>f.status==='accepted').map(f=>f.requester===me.id?f.addressee:f.requester).filter(i=>names.includes(uname(i).toLowerCase()));\n  if(!ids.length)return alert('Add at least one friend you are already connected with.');\n  openConv(await mk(name,true,ids));\n}\n\n/* ---------- Messages ---------- */\nlet M={},R={},online=new Set(),tch,lastT=0,tmr,typing=false,rep=null,edit=null;\nconst EM=['👍','❤️','😂','😮','😢'];\nfunction status(){\n  const c=convs.find(c=>c.id===cur),on=!!c&&!c.is_group&&online.has(other(c));\n  $('st').textContent=!c?'':typing?'typing…':c.is_group?c.conversation_members.length+' members':on?'Online':'Offline';\n  $('st').classList.toggle('ok',typing||on);\n}\nfunction paint(){\n  document.querySelectorAll('#chats [data-c]').forEach(r=>{const c=convs.find(c=>c.id===r.dataset.c);r.classList.toggle('onl',!!c&&!c.is_group&&online.has(other(c)))});\n  status();\n}\nfunction bar(){\n  const r=$('rp');r.hidden=!(rep||edit);\n  r.innerHTML=(edit?'Editing message':rep?'Replying to '+esc(uname(rep.sender_id)):'')+' <button type=\"button\" class=\"g\" id=\"rx\">✕</button>';\n  $('rx').onclick=()=>{if(edit)$('mi').value='';rep=edit=null;bar()};\n}\nasync function loadReacts(){\n  const ids=Object.keys(M);R={};\n  if(ids.length){const {data}=await sb.from('reactions').select('*').in('message_id',ids);(data||[]).forEach(r=>(R[r.message_id]=R[r.message_id]||[]).push(r))}\n  Object.values(M).forEach(addMsg);\n}\nasync function openConv(id){\n  cur=id;const c=convs.find(c=>c.id===id);rep=edit=null;typing=false;bar();\n  $('app').classList.add('open');$('head').hidden=false;$('send').hidden=false;\n  $('cn').textContent=cname(c);$('ca').hidden=$('cv').hidden=c.is_group;$('ad').hidden=!c.is_group;\n  document.querySelectorAll('#chats .row').forEach(r=>r.classList.toggle('on',r.dataset.c===id));\n  if(tch)sb.removeChannel(tch);\n  tch=sb.channel('typing:'+id);\n  tch.on('broadcast',{event:'t'},({payload})=>{if(payload.u===me.id)return;typing=true;status();clearTimeout(tmr);tmr=setTimeout(()=>{typing=false;status()},2500)}).subscribe();\n  const {data}=await sb.from('messages').select('*').eq('conversation_id',id).order('created_at');\n  M={};R={};$('msgs').innerHTML='';(data||[]).forEach(m=>M[m.id]=m);\n  const ids=Object.keys(M);\n  if(ids.length){const {data:rx}=await sb.from('reactions').select('*').in('message_id',ids);(rx||[]).forEach(r=>(R[r.message_id]=R[r.message_id]||[]).push(r))}\n  (data||[]).forEach(addMsg);status();\n}\nfunction addMsg(m){\n  M[m.id]=m;let d=document.querySelector(`[data-id=\"${m.id}\"]`);const n=!d;\n  if(n){d=document.createElement('div');d.dataset.id=m.id}\n  d.className='m'+(m.sender_id===me.id?' me':'');\n  const q=m.reply_to&&M[m.reply_to],rs={};(R[m.id]||[]).forEach(r=>(rs[r.emoji]=rs[r.emoji]||[]).push(r.user_id));\n  let h=`<small>${esc(uname(m.sender_id))} · ${new Date(m.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}${m.edited?' · edited':''}</small>`;\n  if(q)h+=`<div class=\"q\">${esc(uname(q.sender_id))}: ${esc(q.deleted?'Deleted message':pretty(q.body)||q.file_name||'File')}</div>`;\n  if(m.deleted)h+='<i class=\"mut\">Message deleted</i>';\n  else{\n    if(m.file_url&&/^https:\\/\\//.test(m.file_url))h+=/^image\\//.test(m.file_type||'')?`<a href=\"${esc(m.file_url)}\" target=\"_blank\" rel=\"noopener\"><img src=\"${esc(m.file_url)}\" alt=\"\"></a>`:`<a class=\"fl\" href=\"${esc(m.file_url)}\" target=\"_blank\" rel=\"noopener\">📎 ${esc(m.file_name||'File')}</a>`;\n    const pm=m.body&&m.body.match(/^::party::([a-z0-9]{3,32})::(.*)$/);\n    if(pm)h+=`<div class=\"pty\"><b>🎮 ${esc(pm[2])}</b><span>Eaglercraft party · code ${pm[1]}</span><div><button data-a=\"play\" data-c=\"${pm[1]}\">Play here</button><button class=\"g\" data-a=\"tab\" data-c=\"${pm[1]}\">New tab</button></div></div>`;\n    else if(m.body&&/^::game::/.test(m.body)){const g=m.body.match(/^::game::(\\S+?)::(.*)$/),u=g&&gameUrl(g[1]);\n      h+=u?`<div class=\"pty\"><b>🕹️ ${esc(g[2])}</b><span>${esc(new URL(u).host)}</span><div><button data-a=\"game\" data-r=\"${esc(g[1])}\" data-t=\"${esc(g[2])}\">Play here</button><button class=\"g\" data-a=\"gtab\" data-r=\"${esc(g[1])}\">New tab</button></div></div>`:`<div>${esc(m.body)}</div>`}\n    else if(m.body)h+=`<div>${esc(m.body)}</div>`;\n    h+='<button class=\"mb\" data-a=\"menu\" aria-label=\"Message actions\">⋯</button>';\n  }\n  const k=Object.keys(rs);\n  if(k.length)h+='<div class=\"rx\">'+k.map(e=>`<span data-a=\"re\" data-e=\"${e}\" class=\"${rs[e].includes(me.id)?'mine':''}\">${e} ${rs[e].length}</span>`).join('')+'</div>';\n  d.innerHTML=h;if(n){$('msgs').append(d);$('msgs').scrollTop=1e9}\n}\nasync function react(id,e){\n  const x=(R[id]||[]).find(r=>r.user_id===me.id&&r.emoji===e);\n  if(x)await sb.from('reactions').delete().match({message_id:id,user_id:me.id,emoji:e});\n  else await sb.from('reactions').insert({message_id:id,user_id:me.id,emoji:e});\n  loadReacts();\n}\n$('msgs').onclick=e=>{\n  const t=e.target.closest('[data-a]'),d=e.target.closest('[data-id]');\n  document.querySelectorAll('.pop').forEach(p=>p.remove());\n  if(!t||!d)return;const m=M[d.dataset.id];\n  if(t.dataset.a==='re')return react(m.id,t.dataset.e);\n  if(t.dataset.a==='play')return playParty(t.dataset.c);\n  if(t.dataset.a==='tab')return void window.open(partyUrl(t.dataset.c),'_blank','noopener');\n  if(t.dataset.a==='game')return playGame(t.dataset.r,t.dataset.t);\n  if(t.dataset.a==='gtab'){const u=gameUrl(t.dataset.r);return void(u&&window.open(u,'_blank','noopener'))}\n  const p=document.createElement('div');p.className='pop';\n  p.innerHTML=EM.map(x=>`<span data-p=\"${x}\">${x}</span>`).join('')+'<button class=\"g\" data-p=\"reply\">Reply</button>'+(m.sender_id===me.id?(m.body&&!/^::(party|game)::/.test(m.body)?'<button class=\"g\" data-p=\"edit\">Edit</button>':'')+'<button class=\"g\" data-p=\"del\">Delete</button>':'');\n  p.onclick=async ev=>{\n    const a=ev.target.dataset.p;if(!a)return;p.remove();\n    if(EM.includes(a))react(m.id,a);\n    else if(a==='reply'){rep=m;edit=null;bar();$('mi').focus()}\n    else if(a==='edit'){edit=m;rep=null;bar();$('mi').value=m.body;$('mi').focus()}\n    else if(a==='del'){const {error}=await sb.from('messages').update({deleted:true,body:null,file_url:null}).eq('id',m.id);if(error)alert(error.message)}\n  };\n  d.append(p);\n};\n$('send').onsubmit=async e=>{\n  e.preventDefault();const body=$('mi').value.trim();if(!body||!cur)return;$('mi').value='';\n  if(edit){const id=edit.id;edit=null;bar();const {error}=await sb.from('messages').update({body,edited:true}).eq('id',id);if(error)alert(error.message);return}\n  if(await eagler(body)||await gameCmd(body))return;\n  const row={conversation_id:cur,sender_id:me.id,body};if(rep)row.reply_to=rep.id;rep=null;bar();\n  const {error}=await sb.from('messages').insert(row);if(error)alert(error.message);\n};\n$('mi').oninput=()=>{if(tch&&Date.now()-lastT>1500){lastT=Date.now();tch.send({type:'broadcast',event:'t',payload:{u:me.id}})}};\n$('at').onclick=()=>$('fi').click();\n$('fi').onchange=async()=>{\n  const f=$('fi').files[0];$('fi').value='';if(!f||!cur)return;\n  if(f.size>10e6)return alert('Files can be up to 10 MB.');\n  const path=`${me.id}/${Date.now()}_${f.name.replace(/[^\\w.\\-]/g,'_')}`;\n  const {error}=await sb.storage.from('chat-files').upload(path,f);if(error)return alert(error.message);\n  const {data}=sb.storage.from('chat-files').getPublicUrl(path);\n  const row={conversation_id:cur,sender_id:me.id,body:$('mi').value.trim()||null,file_url:data.publicUrl,file_name:f.name,file_type:f.type||'file'};\n  if(rep){row.reply_to=rep.id;rep=null;bar()}$('mi').value='';\n  const {error:e2}=await sb.from('messages').insert(row);if(e2)alert(e2.message);\n};\n$('back').onclick=()=>$('app').classList.remove('open');\n\n/* ---------- Calls: WebRTC signaled over Supabase Realtime broadcast ---------- */\nlet pc,stream,peer,pend=[],chans={},inc=null,ring;\nconst ICE={iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:['turn:openrelay.metered.ca:80','turn:openrelay.metered.ca:443','turn:openrelay.metered.ca:443?transport=tcp'],username:'openrelayproject',credential:'openrelayproject'}]};\n// wait until the channel is really joined before sending, so offers and ICE are never lost\nconst sch=id=>chans[id]||(chans[id]=new Promise((res,rej)=>{const c=sb.channel('u:'+id);\n  c.subscribe(st=>{if(st==='SUBSCRIBED')res(c);else if(['CHANNEL_ERROR','TIMED_OUT','CLOSED'].includes(st)){delete chans[id];sb.removeChannel(c);rej(new Error(st))}})}));\n// send with one retry on a fresh channel; returns true when delivered to the server\nasync function sig(to,p){\n  for(let i=0;i<2;i++){\n    try{\n      const c=await Promise.race([sch(to),new Promise((_,j)=>setTimeout(()=>j(new Error('timeout')),6000))]);\n      if(await c.send({type:'broadcast',event:'sig',payload:{...p,from:me.id}})==='ok')return true;\n    }catch(e){}\n    const old=chans[to];delete chans[to];if(old)old.then(c=>sb.removeChannel(c)).catch(()=>{});\n  }\n  return false;\n}\n// wait for ICE gathering so the whole offer/answer goes in ONE message (no trickle, no rate limits)\nconst gathered=()=>new Promise(r=>{if(pc.iceGatheringState==='complete')return r();\n  const f=()=>{if(pc.iceGatheringState==='complete'){pc.removeEventListener('icegatheringstatechange',f);r()}};\n  pc.addEventListener('icegatheringstatechange',f);setTimeout(r,2500)});\nasync function setup(video){\n  stream=await navigator.mediaDevices.getUserMedia({audio:true,video});\n  $('lv').srcObject=stream;$('lv').hidden=!video;\n  pc=new RTCPeerConnection(ICE);\n  stream.getTracks().forEach(t=>pc.addTrack(t,stream));\n  pc.ontrack=e=>{$('rv').srcObject=e.streams[0];$('rv').play().catch(()=>{})};\n  pc.onconnectionstatechange=()=>{const s=pc&&pc.connectionState;\n    if(s==='connected'){clearTimeout(ring);$('cs').textContent='Connected'}\n    if(s==='failed')$('cs').textContent='Connection failed. Your network may block calls.';\n    if(s==='disconnected')$('cs').textContent='Reconnecting…'};\n  $('call').hidden=false;$('cs').textContent='Calling '+uname(peer)+'…';$('mu').textContent='Mute';\n}\nasync function startCall(video){\n  const c=convs.find(c=>c.id===cur);if(!c||c.is_group)return;\n  if(pc&&pc.connectionState==='connected')return;\n  if(inc){sig(inc.from,{t:'end'});inc=null;$('inc').hidden=true}\n  if(pc)hang(true);\n  peer=other(c);\n  try{await setup(video)}catch(e){hang(false);return alert('Allow microphone'+(video?' and camera':'')+' access to call.')}\n  const o=await pc.createOffer();await pc.setLocalDescription(o);await gathered();\n  if(!pc)return;\n  if(!(await sig(peer,{t:'offer',sdp:pc.localDescription,video}))){hang(false);return alert('Couldn’t reach the call server. Check your connection and try again.')}\n  ring=setTimeout(()=>{if(pc&&pc.connectionState!=='connected'){hang(true);alert('No answer.')}},45000);\n}\n$('ca').onclick=()=>startCall(false);$('cv').onclick=()=>startCall(true);\nasync function flush(){for(const c of pend)await pc.addIceCandidate(c).catch(()=>{});pend=[]}\nasync function onSig(p){\n  if(p.t==='offer'){\n    if(inc&&inc.from===p.from)inc=null;\n    if(pc&&pc.connectionState!=='connected'&&p.from===peer)hang(false);\n    if(pc||inc)return sig(p.from,{t:'busy'});\n    inc=p;p.x=setTimeout(()=>{if(inc===p){inc=null;$('inc').hidden=true}},50000);ping(uname(p.from),p.video?'Incoming video call':'Incoming voice call','call');$('in').textContent=uname(p.from);$('it').textContent=p.video?'Incoming video call':'Incoming voice call';$('inc').hidden=false;\n  }else if(p.t==='answer'&&pc&&p.from===peer){await pc.setRemoteDescription(p.sdp);await flush()}\n  else if(p.t==='ice'){pc&&pc.remoteDescription?pc.addIceCandidate(p.c).catch(()=>{}):pend.push(p.c)}\n  else if(p.t==='end'&&inc&&p.from===inc.from){inc=null;pend=[];$('inc').hidden=true}\n  else if((p.t==='end'||p.t==='busy')&&pc&&p.from===peer){if(p.t==='busy')alert('They are on another call.');hang(false)}\n}\n$('ac').onclick=async()=>{\n  const p=inc;inc=null;$('inc').hidden=true;peer=p.from;\n  try{await setup(p.video)}catch(e){hang(true);return alert('Allow microphone'+(p.video?' and camera':'')+' access to answer.')}\n  await pc.setRemoteDescription(p.sdp);await flush();\n  const a=await pc.createAnswer();await pc.setLocalDescription(a);await gathered();\n  if(!pc)return;if(!(await sig(peer,{t:'answer',sdp:pc.localDescription}))){hang(false);alert('Couldn’t reach them. Try again.')}\n};\n$('dc').onclick=()=>{sig(inc.from,{t:'end'});inc=null;pend=[];$('inc').hidden=true};\n$('mu').onclick=()=>{const t=stream&&stream.getAudioTracks()[0];if(t){t.enabled=!t.enabled;$('mu').textContent=t.enabled?'Mute':'Unmute'}};\nfunction hang(notify){\n  clearTimeout(ring);if(notify&&peer)sig(peer,{t:'end'});\n  stream&&stream.getTracks().forEach(t=>t.stop());pc&&pc.close();\n  pc=stream=peer=null;pend=[];$('call').hidden=true;$('rv').srcObject=$('lv').srcObject=null;\n}\n$('hu').onclick=()=>hang(true);\n\n/* ---------- Settings, profile icon, add members, notifications ---------- */\nconst av=id=>{const u=P[id]&&P[id].avatar_url;return u&&/^https:\\/\\//.test(u)?`--av:url(\"${u.replace(/[\"\\\\()\\s]/g,'')}\")`:''};\nfunction paintSet(){\n  const u=av(me.id);$('who').setAttribute('style',u);$('sav').setAttribute('style',u);$('sun').textContent=uname(me.id);\n  $('sn').textContent=!('Notification' in window)?'Notifications not supported':Notification.permission==='granted'?'Notifications on ✓':Notification.permission==='denied'?'Notifications blocked in browser settings':'Enable notifications';\n}\n$('who').onclick=()=>{paintSet();$('set').hidden=false};\n$('sx').onclick=()=>$('set').hidden=true;\n$('slo').onclick=()=>$('lo').click();\n$('sn').onclick=async()=>{if('Notification' in window&&Notification.permission==='default')await Notification.requestPermission();paintSet()};\n$('sup').onclick=()=>$('sf').click();\n$('sf').onchange=async()=>{\n  const f=$('sf').files[0];$('sf').value='';if(!f)return;\n  try{\n    const img=await createImageBitmap(f),s=Math.min(img.width,img.height),cv=document.createElement('canvas');cv.width=cv.height=256;\n    cv.getContext('2d').drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,256,256);\n    const blob=await new Promise(r=>cv.toBlob(r,'image/jpeg',.85));\n    const path=`${me.id}/${Date.now()}.jpg`;\n    const {error}=await sb.storage.from('avatars').upload(path,blob,{contentType:'image/jpeg'});if(error)throw error;\n    const url=sb.storage.from('avatars').getPublicUrl(path).data.publicUrl;\n    const {error:e2}=await sb.from('profiles').update({avatar_url:url}).eq('id',me.id);if(e2)throw e2;\n    P[me.id].avatar_url=url;paintSet();loadConvs();loadFriends();\n  }catch(e){alert('Couldn’t update your icon: '+(e.message||e))}\n};\n$('ad').onclick=()=>{\n  const c=convs.find(c=>c.id===cur);if(!c||!c.is_group)return;\n  const have=new Set(c.conversation_members.map(m=>m.user_id));\n  const fl=fr.filter(f=>f.status==='accepted').map(f=>f.requester===me.id?f.addressee:f.requester).filter(i=>!have.has(i));\n  $('pl').innerHTML=fl.map(i=>`<label class=\"pk\"><input type=\"checkbox\" value=\"${i}\"><span>${esc(uname(i))}</span></label>`).join('')||'<div class=\"mut\">All your friends are already in this group.</div>';\n  $('pk').hidden=false;\n};\n$('pc').onclick=()=>$('pk').hidden=true;\n$('pa').onclick=async()=>{\n  const ids=[...$('pl').querySelectorAll('input:checked')].map(i=>i.value);if(!ids.length)return;\n  const {error}=await sb.from('conversation_members').insert(ids.map(user_id=>({conversation_id:cur,user_id})));\n  if(error)return alert(error.message);\n  $('pk').hidden=true;\n  await sb.from('messages').insert({conversation_id:cur,sender_id:me.id,body:'➕ '+uname(me.id)+' added '+ids.map(uname).join(', ')});\n  loadConvs();\n};\nlet unread=0;const base=document.title;\nconst away=()=>document.hidden||!document.hasFocus();\nconst seenTab=()=>{unread=0;document.title=base};\naddEventListener('focus',seenTab);document.addEventListener('visibilitychange',()=>{if(!document.hidden)seenTab()});\nfunction toast(t){const e=$('toast');e.textContent=t;e.hidden=false;clearTimeout(e._t);e._t=setTimeout(()=>e.hidden=true,4000)}\n// Browser notification, only when you are not looking at this tab\nfunction ping(title,body,tag,conv){\n  if(!away())return;\n  unread++;document.title=`(${unread}) ${base}`;\n  if(!('Notification' in window)||Notification.permission!=='granted')return;\n  const n=new Notification(title,{body,tag});\n  n.onclick=()=>{window.focus();n.close();if(conv)openConv(conv)};\n}\nfunction notifyMsg(m){\n  if(m.sender_id===me.id||m.deleted)return;\n  const c=convs.find(c=>c.id===m.conversation_id),g=c&&c.is_group;\n  ping(g?cname(c):uname(m.sender_id),(g?uname(m.sender_id)+': ':'')+(pretty(m.body)||'📎 '+(m.file_name||'File')),'c'+m.conversation_id,m.conversation_id);\n}\nfunction onAdded(r){\n  if(r.user_id!==me.id)return;const c=convs.find(c=>c.id===r.conversation_id);\n  if(!c||!c.is_group||c.created_by===me.id)return;\n  if(away())ping('Added to a group','You were added to “'+c.name+'”','c'+c.id,c.id);else toast('You were added to “'+c.name+'”');\n}\n$('gh').onclick=async()=>{\n  const {error}=await sb.auth.signInWithOAuth({provider:'github',options:{redirectTo:location.origin+location.pathname}});\n  if(error)note(error.message);\n};\n\n/* ---------- @eaglercraft party create <event name> [| server] ---------- */\nconst EAGLER_URL='https://minecraft3.33sjayakumar.workers.dev'; // your Eaglercraft launcher\nconst DEFAULT_SERVER='zentic.cc';                                // used when no server is given\nconst EG_SB='https://wzfdomantqeaedfexpgq.supabase.co',EG_KEY='sb_publishable_vrz02Sm0olhxPqgc1MihJg_mrEMh7MG';\nconst EG_ALPHA='abcdefghjkmnpqrstuvwxyz23456789';\nconst partyUrl=c=>`${EAGLER_URL}/party=${c}`;\nconst pretty=b=>{const m=b&&b.match(/^::party::([a-z0-9]{3,32})::(.*)$/),g=b&&b.match(/^::game::(\\S+?)::(.*)$/);return m?'🎮 Party: '+m[2]:g?'🕹️ '+g[2]:b};\nfunction egServer(v){let s=v.trim();if(!/^wss?:\\/\\//i.test(s))s='wss://'+s;try{const u=new URL(s);return /^wss?:$/.test(u.protocol)?u.href:null}catch{return null}}\nasync function makeParty(name,server){\n  for(let i=0;i<5;i++){\n    const code=Array.from(crypto.getRandomValues(new Uint8Array(5)),b=>EG_ALPHA[b%EG_ALPHA.length]).join('');\n    // same request your Create-a-party page makes (anon key), so the existing table rules apply\n    const r=await fetch(EG_SB+'/rest/v1/parties',{method:'POST',headers:{apikey:EG_KEY,Authorization:'Bearer '+EG_KEY,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({code,server,name})});\n    if(r.status===409)continue;\n    return r.ok?code:null;\n  }\n  return null;\n}\nasync function eagler(text){\n  const m=text.match(/^@eaglercraft\\b\\s*(.*)$/i);if(!m)return false;\n  const mm=m[1].match(/^party\\s+create\\s+(.+)$/i);\n  if(!mm){toast('Try: @eaglercraft party create Friday build night');return true}\n  const [nameRaw,srvRaw]=mm[1].split('|'),name=nameRaw.trim().replace(/::/g,' ').slice(0,40);\n  const server=egServer(srvRaw&&srvRaw.trim()?srvRaw:DEFAULT_SERVER);\n  if(!name)return toast('Give your party a name.'),true;\n  if(!server)return toast('That server address doesn’t look right.'),true;\n  toast('Creating your party…');\n  const code=await makeParty(name,server);\n  if(!code)return toast('Couldn’t create the party. Try again.'),true;\n  // the invite is a normal message, so everyone in the group (or the other person in a DM) gets it and is notified\n  const {error}=await sb.from('messages').insert({conversation_id:cur,sender_id:me.id,body:`::party::${code}::${name}`});\n  if(error)alert(error.message);\n  return true;\n}\nfunction playParty(code){openPanel(partyUrl(code),'🎮 Eaglercraft · '+code,false)}\n$('pgx').onclick=()=>{$('pgf').src='about:blank';$('pg').hidden=true};\n\n/* ---------- @game <name or site> : play in the side panel ---------- */\n// Add your own shortcuts here: key (what people type) -> title + url\nconst GAMES={\n  gd:{title:'Geometry Dash',url:'https://gd.horizensearch.com'},\n  bloxd:{title:'Bloxd.io',url:'https://bloxd.io'},\n  minecraft:{title:'Minecraft (Eaglercraft)',url:EAGLER_URL},\n};\nconst gameUrl=r=>GAMES[r]?GAMES[r].url:(/^https:\\/\\/[^\\s:]+$/i.test(r)?r:null);\nfunction gameRef(tok){\n  tok=tok.toLowerCase().replace(/^https?:\\/\\//,'').replace(/^www\\./,'').replace(/\\/$/,'');\n  if(GAMES[tok])return {ref:tok,title:GAMES[tok].title};\n  for(const [k,g] of Object.entries(GAMES))if(new URL(g.url).host===tok)return {ref:k,title:g.title};\n  if(/^[a-z0-9-]+(\\.[a-z0-9-]+)+(\\/[^\\s:]*)?$/.test(tok))return {ref:'https://'+tok,title:tok.split('/')[0]};\n  return null;\n}\nasync function gameCmd(text){\n  const m=text.match(/^@game\\b\\s*(\\S*)/i);if(!m)return false;\n  if(!m[1]||/^(list|help)$/i.test(m[1]))return toast('Try '+Object.keys(GAMES).map(k=>'@game '+k).join(' · ')+' · or any site like @game 2048.org'),true;\n  const g=gameRef(m[1]);if(!g)return toast('Try @game gd, @game bloxd.io or @game list'),true;\n  const {error}=await sb.from('messages').insert({conversation_id:cur,sender_id:me.id,body:`::game::${g.ref}::${g.title}`});\n  if(error)alert(error.message);\n  return true;\n}\nfunction openPanel(url,title,boxed){\n  $('pgt').textContent=title;$('pgo').onclick=()=>window.open(url,'_blank','noopener');\n  const f=$('pgf');f.removeAttribute('src');\n  // sites that aren't in the shortcut list above run sandboxed\n  if(boxed)f.setAttribute('sandbox','allow-scripts allow-same-origin allow-forms allow-pointer-lock allow-popups');else f.removeAttribute('sandbox');\n  f.src=url;$('pg').hidden=false;\n}\nfunction playGame(ref,title){const u=gameUrl(ref);if(u)openPanel(u,'🕹️ '+(title||new URL(u).host),!GAMES[ref])}\n\n/* ---------- auto-create accounts (GitHub / email code) + email code sign-in ---------- */\nasync function ensureAccount(u,verified){\n  const pv=(u.app_metadata&&u.app_metadata.provider)||'';\n  if(!verified&&!['github','google'].includes(pv))return;   // email+password users still confirm by link\n  await sb.from('approved_acounts').upsert({user_id:u.id,email:u.email||null});\n  const {data}=await sb.from('profiles').select('id').eq('id',u.id).maybeSingle();\n  if(!data){\n    const m=u.user_metadata||{},base=String(m.username||m.user_name||m.preferred_username||(u.email||'user').split('@')[0]||'user').replace(/[^\\w.-]/g,'').slice(0,20)||'user';\n    for(let i=0;i<5;i++){const {error}=await sb.from('profiles').insert({id:u.id,username:i?base+Math.floor(Math.random()*900+100):base});if(!error||error.code!=='23505')break}\n  }\n}\n$('oc').onclick=async()=>{\n  const email=$('em').value.trim(),username=$('un').value.trim();\n  if(!email)return note('Enter your email first.');\n  const {error}=await sb.auth.signInWithOtp({email,options:{shouldCreateUser:true,data:username?{username}:{}}});\n  if(error)return note(error.message);\n  $('cd').hidden=$('ov').hidden=false;$('cd').focus();note('Code sent. Check your email (and spam).');\n};\n$('ov').onclick=async()=>{\n  const email=$('em').value.trim(),token=$('cd').value.replace(/\\s/g,'');\n  if(!/^\\d{6,10}$/.test(token))return note('Enter the code from your email.');\n  window.holdBoot=true;\n  try{\n    const {data,error}=await sb.auth.verifyOtp({email,token,type:'email'});\n    if(error)return note(error.message);\n    await ensureAccount(data.user,true);   // a correct code proves the email, so the account is activated\n  }finally{window.holdBoot=false}\n  boot();\n};\n</script>\n</body></html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed', { status: 405 });
    if (url.pathname === '/favicon.ico') return new Response(null, { status: 204 });
    return new Response(request.method === 'HEAD' ? null : HTML, {
      headers: {
        'content-type': 'text/html; charset=utf-8',
        'cache-control': 'no-cache',
        // lets Horizen OS show Messages in a tab
        'content-security-policy': "frame-ancestors 'self' https://horizensearch.com https://www.horizensearch.com",
        'referrer-policy': 'strict-origin-when-cross-origin',
      },
    });
  },
};
